from pathlib import Path
import json,hashlib
import numpy as np,pandas as pd
O=Path(__file__).resolve().parents[1];s=pd.read_csv(O/'05_C5_LLPS_enrichment/model_enrichment_sensitivity.tsv',sep='\t');a=pd.read_csv(O/'05_C5_LLPS_enrichment/adjusted_model_sensitivity.tsv',sep='\t');s=s[s.unit=='patient'];a=a[a.unit=='patient'];rows=[];joint=[]
def positives(g):return set(g.loc[(g.FDR<.05)&(g.ci_low>0),'niche'].astype(str))
for model,g in s.groupby('model'):
 sets={f:positives(h) for f,h in g.groupby('feature')}
